try{const old=JSON.parse(localStorage.getItem(KEY)||'null');if(old&&Array.isArray(old.records))records=old.records;if([VERSION].includes(old?.version)&&old.session&&old.state){session=old.session;trial=old.trial;state=old.state;mission=old.mission;if(state.status==='running')state.status='paused';state.manualSpeed=0;if(state.status==='editing')state.status='review';state.targetAltitude=state.altitude;state.trail=state.trail||FlightControls.travelled(state.route,state.progress);log('restore','恢复任务','刷新后保持暂停')}else{fresh();log('session_start','开始会话',old?'升级界面，保留既往记录':'进入飞行界面')}}catch{fresh();toast('旧记录无法读取；本次不会覆盖旧记录，请先联系研究者');throw Error('Stored data unavailable')}
