 session={id:crypto.randomUUID(),...nextConfig};trial=crypto.randomUUID();mission=next;
 state={status:'review',route:C.clone(next.route),progress:0,altitude,targetAltitude:altitude,speed,battery:next.battery,simTime:0,goalDeferred:false,presentedAt:Date.now(),trail};draft=null;
